# Reads raw/inf_5.0.json, inf_5.1.json, inf_6.0.json and inf_6.1.json. python3 -I check_claims_supp61.py
import json,hashlib,re
FILES=['raw/inf_5.0.json','raw/inf_6.0.json','raw/inf_6.1.json']
RAW={f:open(f,'rb').read() for f in FILES}
V5=json.loads(RAW['raw/inf_5.0.json']); V0=json.loads(RAW['raw/inf_6.0.json']); B=list(json.loads(RAW['raw/inf_6.1.json']).values())
s=str; pc=lambda x,y:100*(x/y-1)
def b(org,sysn,m,sc,div='closed',n=None):
    r=[x for x in B if x['Organization']==org and (sysn in x['SystemName'] if not sysn.startswith('=') else x['SystemName']==sysn[1:]) and x['Model']==m and x['Scenario'].lower()==sc.lower() and x['Division']==div and (n is None or x['total_accelerators']==n)]
    assert len(r)==1,(org,sysn,m,sc,div,n,len(r)); return r[0]['Result']
def a(i,m,sc):
    r=[x for x in V0 if x['ID']==i and x['Model']==m and x['Scenario']==sc and x['Category']=='closed']; assert len(r)==1,(i,m,sc,len(r)); return r[0]['Performance_Result']
def mk(i,q,calc,st,got,out,note): return dict(id=i,quote=q,calc=calc,stated=st,delivered=got,outcome=out,note=note,label_mismatch=False)
ok=lambda c,y='CONSISTENT',n='BELOW':y if c else n
